def add_room_effect(sig, rng):
    """叠加距离衰减、房间混响与本底噪声，模拟近/远距离与家庭背景。"""
    n = sig.size
    # 简易混响：若干衰减抽头
    out = sig.copy()
    for _ in range(rng.integers(2, 5)):
        delay = int(rng.uniform(0.01, 0.08) * SAMPLE_RATE)
        gain = rng.uniform(0.05, 0.25)
        out[delay:] += gain * sig[:n - delay]

