def resample_linear(x, sr_in, sr_out=TARGET_SR):
    if sr_in == sr_out:
        return x
    n_out = int(round(x.size * sr_out / sr_in))
    if n_out <= 1:
        return np.zeros(0)
    t_in = np.arange(x.size)
    t_out = np.linspace(0, x.size - 1, n_out)
    return np.interp(t_out, t_in, x)


