8	#include <math.h>
9	#include <stdlib.h>
10	#include <string.h>
11	
12	#include "velaguard/vg_feature.h"
13	
14	/****************************************************************************
15	 * Pre-processor Definitions
16	 ****************************************************************************/
17	
18	#define VG_PREEMPH   0.97f
19	#define VG_MEL_LOW   20.0f
20	#define VG_MEL_HIGH  7800.0f
21	#define VG_EPS       1e-10f
22	
23	#ifndef M_PI
24	#  define M_PI 3.14159265358979323846
25	#endif
26	
27	/****************************************************************************
28	 * Private Data
29	 ****************************************************************************/
30	
31	static float g_hamming[VG_FRAME_LEN];
32	static float g_mel_fb[VG_NUM_MEL][VG_FFT_SIZE / 2 + 1];
33	static float g_dct[VG_NUM_MFCC][VG_NUM_MEL];
34	static int   g_fft_rev[VG_FFT_SIZE];
35	static float g_cos_tab[VG_FFT_SIZE / 2];
36	static float g_sin_tab[VG_FFT_SIZE / 2];
37	static int   g_tables_ready;
38	
39	/****************************************************************************
40	 * Private Functions
41	 ****************************************************************************/
42	
43	static float vg_hz2mel(float hz)
44	{
45	  return 2595.0f * log10f(1.0f + hz / 700.0f);
46	}
47	
48	static float vg_mel2hz(float mel)
49	{
50	  return 700.0f * (powf(10.0f, mel / 2595.0f) - 1.0f);
51	}
52	
53	static void vg_build_tables(void)
54	{
55	  float mel_low;
56	  float mel_high;
57	  float points[VG_NUM_MEL + 2];
58	  int bins[VG_NUM_MEL + 2];
59	  int i;
60	  int j;
61	  int bits = 0;
62	  int n = VG_FFT_SIZE;
63	
64	  if (g_tables_ready)
65	    {
66	      return;
67	    }
68	
69	  for (i = 0; i < VG_FRAME_LEN; i++)
70	    {
71	      g_hamming[i] = 0.54f - 0.46f *
72	                     cosf(2.0f * (float)M_PI * i / (VG_FRAME_LEN - 1));
73	    }
74	
75	  /* FFT 位反转表与旋转因子 */
76	
77	  while ((1 << bits) < n)
78	    {
79	      bits++;
80	    }
81	
82	  for (i = 0; i < n; i++)
83	    {
84	      int r = 0;
85	
86	      for (j = 0; j < bits; j++)
87	        {
88	          r |= ((i >> j) & 1) << (bits - 1 - j);
89	        }
90	
91	      g_fft_rev[i] = r;
92	    }
93	
94	  for (i = 0; i < n / 2; i++)
95	    {
96	      g_cos_tab[i] = cosf(-2.0f * (float)M_PI * i / n);
97	      g_sin_tab[i] = sinf(-2.0f * (float)M_PI * i / n);
98	    }
99	
100	  /* Mel 滤波器组 */
101	
102	  mel_low = vg_hz2mel(VG_MEL_LOW);
103	  mel_high = vg_hz2mel(VG_MEL_HIGH);
104	
105	  for (i = 0; i < VG_NUM_MEL + 2; i++)
106	    {
107	      points[i] = vg_mel2hz(mel_low +
108	                            (mel_high - mel_low) * i / (VG_NUM_MEL + 1));
109	      bins[i] = (int)floorf((VG_FFT_SIZE + 1) * points[i] / VG_SAMPLE_RATE);
110	      if (bins[i] > VG_FFT_SIZE / 2)
111	        {
112	          bins[i] = VG_FFT_SIZE / 2;
113	        }
114	    }
115	
116	  memset(g_mel_fb, 0, sizeof(g_mel_fb));
117	  for (i = 0; i < VG_NUM_MEL; i++)
118	    {
119	      for (j = bins[i]; j < bins[i + 1]; j++)
120	        {
121	          if (bins[i + 1] > bins[i])
122	            {
123	              g_mel_fb[i][j] = (float)(j - bins[i]) /
124	                               (float)(bins[i + 1] - bins[i]);
125	            }
126	        }
127	
128	      for (j = bins[i + 1]; j < bins[i + 2]; j++)
129	        {
130	          if (bins[i + 2] > bins[i + 1])
131	            {
132	              g_mel_fb[i][j] = (float)(bins[i + 2] - j) /
133	                               (float)(bins[i + 2] - bins[i + 1]);
134	            }
135	        }
136	    }
137	
138	  /* DCT-II 正交化系数 */
139	
140	  for (i = 0; i < VG_NUM_MFCC; i++)
141	    {
142	      for (j = 0; j < VG_NUM_MEL; j++)
143	        {
144	          g_dct[i][j] = cosf((float)M_PI * i * (2.0f * j + 1.0f) /
145	                             (2.0f * VG_NUM_MEL));
146	        }
147	    }
148	
149	  g_tables_ready = 1;
150	}
