152	/* 就地基 2 FFT，re/im 长度 VG_FFT_SIZE */
153	
154	static void vg_fft(float *re, float *im)
155	{
156	  int n = VG_FFT_SIZE;
157	  int len;
158	  int i;
159	
160	  for (i = 0; i < n; i++)
161	    {
162	      int r = g_fft_rev[i];
163	
164	      if (r > i)
165	        {
166	          float t = re[i]; re[i] = re[r]; re[r] = t;
167	          t = im[i]; im[i] = im[r]; im[r] = t;
168	        }
169	    }
170	
171	  for (len = 2; len <= n; len <<= 1)
172	    {
173	      int half = len >> 1;
174	      int step = n / len;
175	
176	      for (i = 0; i < n; i += len)
177	        {
178	          int k;
179	
180	          for (k = 0; k < half; k++)
181	            {
182	              float wr = g_cos_tab[k * step];
183	              float wi = g_sin_tab[k * step];
184	              float xr = re[i + k + half] * wr - im[i + k + half] * wi;
185	              float xi = re[i + k + half] * wi + im[i + k + half] * wr;
186	
187	              re[i + k + half] = re[i + k] - xr;
188	              im[i + k + half] = im[i + k] - xi;
189	              re[i + k] += xr;
190	              im[i + k] += xi;
191	            }
192	        }
193	    }
194	}
