196	/****************************************************************************
197	 * Public Functions
198	 ****************************************************************************/
199	
200	int vg_feature_mfcc(const int16_t *pcm, size_t nsamples, float *mfcc)
201	{
202	  static float re[VG_FFT_SIZE];
203	  static float im[VG_FFT_SIZE];
204	  static float mel[VG_NUM_MEL];
205	  float prev = 0.0f;
206	  int nframes = 0;
207	  size_t off;
208	
209	  if (pcm == NULL || mfcc == NULL || nsamples < VG_FRAME_LEN)
210	    {
211	      return -1;
212	    }
213	
214	  vg_build_tables();
215	
216	  for (off = 0;
217	       off + VG_FRAME_LEN <= nsamples && nframes < VG_MAX_FRAMES;
218	       off += VG_FRAME_HOP)
219	    {
220	      float *out = mfcc + (size_t)nframes * VG_NUM_MFCC;
221	      int i;
222	      int j;
223	
224	      memset(re, 0, sizeof(re));
225	      memset(im, 0, sizeof(im));
226	
227	      /* 预加重 + 加窗 */
228	
229	      prev = (off > 0) ? (float)pcm[off - 1] : 0.0f;
230	      for (i = 0; i < VG_FRAME_LEN; i++)
231	        {
232	          float s = (float)pcm[off + i];
233	
234	          re[i] = (s - VG_PREEMPH * prev) * g_hamming[i] / 32768.0f;
235	          prev = s;
236	        }
237	
238	      vg_fft(re, im);
239	
240	      /* 功率谱 -> mel 能量 */
241	
242	      for (i = 0; i < VG_NUM_MEL; i++)
243	        {
244	          float acc = 0.0f;
245	
246	          for (j = 0; j <= VG_FFT_SIZE / 2; j++)
247	            {
248	              float w = g_mel_fb[i][j];
249	
250	              if (w > 0.0f)
251	                {
252	                  acc += w * (re[j] * re[j] + im[j] * im[j]);
253	                }
254	            }
255	
256	          mel[i] = logf(acc + VG_EPS);
257	        }
258	
259	      /* DCT -> MFCC */
260	
261	      for (i = 0; i < VG_NUM_MFCC; i++)
262	        {
263	          float acc = 0.0f;
264	
265	          for (j = 0; j < VG_NUM_MEL; j++)
266	            {
267	              acc += mel[j] * g_dct[i][j];
268	            }
269	
270	          out[i] = acc / VG_NUM_MEL;
271	        }
272	
273	      nframes++;
274	    }
275	
276	  return nframes;
277	}
278	
279	int vg_feature_extract(const int16_t *pcm, size_t nsamples, float *feat)
280	{
281	  static float mfcc[VG_MAX_FRAMES * VG_NUM_MFCC];
282	  int nframes;
283	  int i;
284	  int f;
285	  size_t k;
286	  uint32_t zc = 0;
287	
288	  if (feat == NULL)
289	    {
290	      return -1;
291	    }
292	
293	  nframes = vg_feature_mfcc(pcm, nsamples, mfcc);
294	  if (nframes <= 0)
295	    {
296	      return -1;
297	    }
298	
299	  for (i = 0; i < VG_NUM_MFCC; i++)
300	    {
301	      float sum = 0.0f;
302	      float sum2 = 0.0f;
303	      float dsum = 0.0f;
304	      float mean;
305	      float var;
306	
307	      for (f = 0; f < nframes; f++)
308	        {
309	          float v = mfcc[(size_t)f * VG_NUM_MFCC + i];
310	
311	          sum += v;
312	          sum2 += v * v;
313	
314	          if (f > 0)
315	            {
316	              dsum += fabsf(v - mfcc[(size_t)(f - 1) * VG_NUM_MFCC + i]);
317	            }
318	        }
319	
320	      mean = sum / nframes;
321	      var = sum2 / nframes - mean * mean;
322	      if (var < 0.0f)
323	        {
324	          var = 0.0f;
325	        }
326	
327	      feat[i] = mean;
328	      feat[VG_NUM_MFCC + i] = sqrtf(var);
329	      feat[VG_NUM_MFCC * 2 + i] =
330	          (nframes > 1) ? dsum / (nframes - 1) : 0.0f;
331	    }
332	
333	  /* 过零率：对瞬态冲击与蜂鸣的区分很有帮助 */
334	
335	  for (k = 1; k < nsamples; k++)
336	    {
337	      if ((pcm[k] >= 0) != (pcm[k - 1] >= 0))
338	        {
339	          zc++;
340	        }
341	    }
342	
343	  feat[VG_FEATURE_DIM - 1] = (nsamples > 1)
344	                             ? (float)zc / (float)(nsamples - 1) : 0.0f;
345	
346	  return VG_FEATURE_DIM;
347	}
348	
349	float vg_feature_energy_db(const int16_t *pcm, size_t nsamples)
350	{
351	  double acc = 0.0;
352	  size_t i;
353	
354	  if (pcm == NULL || nsamples == 0)
355	    {
356	      return -120.0f;
357	    }
358	
359	  for (i = 0; i < nsamples; i++)
360	    {
361	      double v = (double)pcm[i] / 32768.0;
362	
363	      acc += v * v;
364	    }
365	
366	  acc = sqrt(acc / (double)nsamples);
367	  return (float)(20.0 * log10(acc + 1e-9));
368	}
