82	  float h[VG_ENV_HIDDEN > VG_VOICE_HIDDEN ?
83	          VG_ENV_HIDDEN : VG_VOICE_HIDDEN];
84	  float out[VG_ENV_CLASSES > VG_VOICE_CLASSES ?
85	            VG_ENV_CLASSES : VG_VOICE_CLASSES];
86	  uint64_t t0 = vg_micros();
87	  uint64_t dt;
88	  int best = 0;
89	  int i;
90	  int j;
91	
92	  for (i = 0; i < VG_FEATURE_DIM; i++)
93	    {
94	      float s = (scale[i] > 1e-6f) ? scale[i] : 1.0f;
95	
96	      norm[i] = (feat[i] - mean[i]) / s;
97	    }
98	
99	  for (i = 0; i < hidden; i++)
100	    {
101	      float acc = 0.0f;
102	
103	      for (j = 0; j < VG_FEATURE_DIM; j++)
104	        {
105	          acc += (float)w1[i * VG_FEATURE_DIM + j] * norm[j];
106	        }
107	
108	      acc = acc * w1_scale + b1[i];
109	      h[i] = (acc > 0.0f) ? acc : 0.0f;   /* ReLU */
110	    }
111	
112	  for (i = 0; i < classes; i++)
113	    {
114	      float acc = 0.0f;
115	
116	      for (j = 0; j < hidden; j++)
117	        {
118	          acc += (float)w2[i * hidden + j] * h[j];
119	        }
120	
121	      out[i] = acc * w2_scale + b2[i];
122	    }
123	
124	  vg_softmax(out, classes);
125	
126	  for (i = 1; i < classes; i++)
127	    {
128	      if (out[i] > out[best])
129	        {
130	          best = i;
131	        }
132	    }
133	
134	  if (probs != NULL)
135	    {
136	      memcpy(probs, out, sizeof(float) * (size_t)classes);
137	    }
138	
139	  dt = vg_micros() - t0;
140	  g_infer_count++;
141	  g_infer_total_us += dt;
142	  if ((uint32_t)dt > g_infer_max_us)
143	    {
144	      g_infer_max_us = (uint32_t)dt;
145	    }
146	
147	  return best;
148	}
