153	
154	vg_sound_class_t vg_classify_env(const float *feat, float *probs)
155	{
156	  int best;
157	
158	  if (feat == NULL)
159	    {
160	      return VG_SOUND_OTHER;
161	    }
162	
163	  best = vg_mlp_forward(feat, g_vg_env_mean, g_vg_env_scale,
164	                        &g_vg_env_w1[0][0], g_vg_env_w1_scale, g_vg_env_b1,
165	                        VG_ENV_HIDDEN,
166	                        &g_vg_env_w2[0][0], g_vg_env_w2_scale, g_vg_env_b2,
167	                        VG_ENV_CLASSES, probs);
168	
169	  return (vg_sound_class_t)best;
170	}
171	
172	vg_voice_kind_t vg_classify_voice(const float *feat, float *probs)
173	{
174	  static const vg_voice_kind_t map[VG_VOICE_CLASSES] =
175	    {
176	      VG_VOICE_NONE, VG_VOICE_MOAN, VG_VOICE_SCREAM, VG_VOICE_SHOUT_HELP
177	    };
178	  int best;
179	
180	  if (feat == NULL)
181	    {
182	      return VG_VOICE_NONE;
183	    }
184	
185	  best = vg_mlp_forward(feat, g_vg_voice_mean, g_vg_voice_scale,
186	                        &g_vg_voice_w1[0][0], g_vg_voice_w1_scale,
187	                        g_vg_voice_b1, VG_VOICE_HIDDEN,
188	                        &g_vg_voice_w2[0][0], g_vg_voice_w2_scale,
189	                        g_vg_voice_b2, VG_VOICE_CLASSES, probs);
190	
191	  return map[best];
192	}
