17	 * Private Data
18	 ****************************************************************************/
19	
20	static int16_t             g_window[VG_WINDOW_SAMPLES];
21	static size_t              g_filled;
22	static bool                g_window_ready;
23	static vg_detector_stats_t g_stats;
24	static uint64_t            g_total_us;
25	static float               g_silence_db = -55.0f;
26	static bool                g_dry_run;
