28	/****************************************************************************
29	 * Private Functions
30	 ****************************************************************************/
31	
32	static uint64_t vg_micros(void)
33	{
34	  struct timespec ts;
35	
36	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
37	    {
38	      return 0;
39	    }
40	
41	  return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)(ts.tv_nsec / 1000);
42	}
43	
44	/* 急促程度估计：类别基线 + 能量修正，范围 0~1 */
45	
46	static float vg_estimate_urgency(vg_voice_kind_t kind, float energy_db,
47	                                 float zcr)
48	{
49	  float base;
50	
51	  switch (kind)
52	    {
53	      case VG_VOICE_SCREAM:
54	        base = 0.85f;
55	        break;
56	
57	      case VG_VOICE_SHOUT_HELP:
58	        base = 0.75f;
59	        break;
60	
61	      case VG_VOICE_MOAN:
62	        base = 0.30f;
63	        break;
64	
65	      default:
66	        base = 0.20f;
67	        break;
68	    }
69	
70	  /* 越响、过零率越高，通常越急促 */
71	
72	  base += (energy_db + 40.0f) / 200.0f;
73	  base += zcr * 0.2f;
74	
75	  if (base < 0.0f)
76	    {
77	      base = 0.0f;
78	    }
79	
80	  if (base > 1.0f)
81	    {
82	      base = 1.0f;
83	    }
84	
85	  return base;
86	}
