117	int vg_detector_process_window(const int16_t *pcm, size_t nsamples)
118	{
119	  float feat[VG_FEATURE_DIM];
120	  float env_probs[VG_ENV_CLASSES];
121	  float voice_probs[VG_VOICE_CLASSES];
122	  vg_enroll_match_t match;
123	  vg_sound_class_t cls;
124	  vg_voice_kind_t kind;
125	  uint64_t t0 = vg_micros();
126	  uint64_t dt;
127	  float energy;
128	  uint64_t now;
129	
130	  if (pcm == NULL || nsamples < VG_FRAME_LEN)
131	    {
132	      return -1;
133	    }
134	
135	  now = vg_now_ms();
136	  energy = vg_feature_energy_db(pcm, nsamples);
137	  g_stats.last_energy_db = energy;
138	  g_stats.windows++;
139	
140	  if (energy < g_silence_db)
141	    {
142	      /* 静音窗口：不推理，直接返回 */
143	
144	      g_stats.last_sound = VG_SOUND_OTHER;
145	      g_stats.last_voice = VG_VOICE_NONE;
146	      return 0;
147	    }
148	
149	  if (vg_feature_extract(pcm, nsamples, feat) < 0)
150	    {
151	      return -1;
152	    }
153	
154	  /* 通道 1：环境声景 */
155	
156	  cls = vg_classify_env(feat, env_probs);
157	  g_stats.last_sound = cls;
158	  g_stats.last_sound_conf = env_probs[cls];
159	
160	  if (cls != VG_SOUND_OTHER)
161	    {
162	      vg_sound_obs_t obs;
163	
164	      memset(&obs, 0, sizeof(obs));
165	      obs.ts_ms = now;
166	      obs.cls = cls;
167	      obs.confidence = env_probs[cls];
168	      obs.window_ms = (uint16_t)(nsamples * 1000 / VG_SAMPLE_RATE);
169	
170	      g_stats.sound_hits++;
171	      if (!g_dry_run)
172	        {
173	          vg_sm_feed_sound(&obs);
174	        }
175	    }
176	
177	  /* 通道 2：人声异常 */
178	
179	  kind = vg_classify_voice(feat, voice_probs);
180	  g_stats.last_voice = kind;
181	  g_stats.last_voice_conf = voice_probs[kind == VG_VOICE_NONE ? 0 :
182	                                        (kind == VG_VOICE_MOAN ? 1 :
183	                                         (kind == VG_VOICE_SCREAM ? 2 : 3))];
184	
185	  if (kind != VG_VOICE_NONE)
186	    {
187	      vg_distress_obs_t obs;
188	
189	      memset(&obs, 0, sizeof(obs));
190	      obs.ts_ms = now;
191	      obs.kind = kind;
192	      obs.confidence = g_stats.last_voice_conf;
193	      obs.urgency = vg_estimate_urgency(kind, energy,
194	                                        feat[VG_FEATURE_DIM - 1]);
195	      obs.repeat_count = 1;
196	
197	      g_stats.voice_hits++;
198	      if (!g_dry_run)
199	        {
200	          vg_sm_feed_distress(&obs);
201	        }
202	    }
203	
204	  /* 通道 3：个性化模板（姓名 / 称呼 / 求救词 / 方言） */
205	
206	  if (vg_enroll_match(feat, &match) == 0)
207	    {
208	      vg_distress_obs_t obs;
209	
210	      memset(&obs, 0, sizeof(obs));
211	      obs.ts_ms = now;
212	      obs.kind = (match.kind == VG_TPL_NAME) ?
213	                 VG_VOICE_NAME_CALL : VG_VOICE_HELP_PHRASE;
214	      obs.confidence = match.score;
215	      obs.repeat_count = 1;
216	
217	      /* 模板本身区分平静/急促，比能量估计更可靠 */
218	
219	      obs.urgency = (match.style == VG_TPL_URGENT) ? 0.85f : 0.20f;
220	      if (kind == VG_VOICE_SCREAM || kind == VG_VOICE_SHOUT_HELP)
221	        {
222	          obs.urgency = 0.95f;
223	        }
224	
225	      vg_strlcpy(obs.matched_phrase, match.phrase, sizeof(obs.matched_phrase));
226	      vg_strlcpy(obs.person_label, match.person, sizeof(obs.person_label));
227	
228	      g_stats.template_hits++;
229	      if (!g_dry_run)
230	        {
231	          vg_sm_feed_distress(&obs);
232	        }
233	    }
234	
235	  dt = vg_micros() - t0;
236	  g_total_us += dt;
237	  if ((uint32_t)dt > g_stats.max_us)
238	    {
239	      g_stats.max_us = (uint32_t)dt;
240	    }
241	
242	  g_stats.avg_us = (uint32_t)(g_total_us / g_stats.windows);
243	  return 1;
244	}
245	
246	int vg_detector_pump(void)
247	{
248	  int n;
249	
250	  if (vg_capture_source() == VG_SRC_NONE)
251	    {
252	      return 0;
253	    }
254	
255	  if (!g_window_ready)
256	    {
257	      /* 首个窗口：填满 1 秒 */
258	
259	      n = vg_capture_read(g_window + g_filled, VG_WINDOW_SAMPLES - g_filled);
260	      if (n <= 0)
261	        {
262	          return 0;
263	        }
264	
265	      g_filled += (size_t)n;
266	      if (g_filled < VG_WINDOW_SAMPLES)
267	        {
268	          return 0;
269	        }
270	
271	      g_window_ready = true;
272	      return vg_detector_process_window(g_window, VG_WINDOW_SAMPLES) > 0
273	             ? 1 : 0;
274	    }
275	
276	  /* 后续窗口：50% 重叠，滑入半秒新数据 */
277	
278	  memmove(g_window, g_window + VG_HOP_SAMPLES,
279	          (VG_WINDOW_SAMPLES - VG_HOP_SAMPLES) * sizeof(int16_t));
280	
281	  n = vg_capture_read(g_window + (VG_WINDOW_SAMPLES - VG_HOP_SAMPLES),
282	                      VG_HOP_SAMPLES);
283	  if (n <= 0)
284	    {
285	      /* 数据不足：把窗口移回原位，等待下次 */
286	
287	      memmove(g_window + VG_HOP_SAMPLES, g_window,
288	              (VG_WINDOW_SAMPLES - VG_HOP_SAMPLES) * sizeof(int16_t));
289	      return 0;
290	    }
291	
292	  if ((size_t)n < VG_HOP_SAMPLES)
293	    {
294	      memset(g_window + (VG_WINDOW_SAMPLES - VG_HOP_SAMPLES) + n, 0,
295	             (VG_HOP_SAMPLES - (size_t)n) * sizeof(int16_t));
296	    }
297	
298	  return vg_detector_process_window(g_window, VG_WINDOW_SAMPLES) > 0 ? 1 : 0;
299	}
300	
301	int vg_detector_run_file(const char *path)
302	{
303	  bool was_virtual = vg_time_is_virtual();
304	  int windows = 0;
305	
306	  if (vg_capture_open(VG_SRC_WAV, path) < 0)
307	    {
308	      return -1;
309	    }
310	
311	  g_filled = 0;
312	  g_window_ready = false;
313	
314	  /* wav 回放远快于实时，必须用虚拟时钟按窗口节奏推进，
315	   * 否则持续时间类规则（水流 30s/120s、报警连续 5s）永远无法触发。
316	   */
317	
318	  vg_time_use_virtual(true);
319	
320	  while (1)
321	    {
322	      bool first = !g_window_ready;
323	
324	      if (vg_detector_pump() <= 0)
325	        {
326	          break;
327	        }
328	
329	      windows++;
330	
331	      /* 首窗覆盖 1 秒，其后每窗推进 0.5 秒（50% 重叠） */
332	
333	      vg_time_virtual_advance(first ? 1000 : VG_HOP_SAMPLES * 1000 /
334	                                             VG_SAMPLE_RATE);
335	      vg_sm_tick();
336	    }
337	
338	  vg_capture_close();
339	  vg_time_use_virtual(was_virtual);
340	  return windows;
341	}
342	
343	void vg_detector_stats(vg_detector_stats_t *out)
344	{
345	  if (out != NULL)
346	    {
347	      *out = g_stats;
348	    }
349	}
350	
351	void vg_detector_stats_reset(void)
352	{
353	  memset(&g_stats, 0, sizeof(g_stats));
354	  g_total_us = 0;
355	  vg_classifier_perf_reset();
356	}
