/* 急促程度估计：类别基线 + 能量修正，范围 0~1 */

static float vg_estimate_urgency(vg_voice_kind_t kind, float energy_db,
                                 float zcr)
{
  float base;

  switch (kind)
    {
      case VG_VOICE_SCREAM:
        base = 0.85f;
        break;

      case VG_VOICE_SHOUT_HELP:
        base = 0.75f;
        break;

      case VG_VOICE_MOAN:
        base = 0.30f;
        break;

      default:
        base = 0.20f;
        break;
    }

  /* 越响、过零率越高，通常越急促 */

  base += (energy_db + 40.0f) / 200.0f;
  base += zcr * 0.2f;

  if (base < 0.0f)
    {
      base = 0.0f;
    }

  if (base > 1.0f)
    {
      base = 1.0f;
    }

  return base;
}

